import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{r as t}from"./ThemeToggle-vCpx62jE.js";import{C as n,M as r,N as i,O as a,P as o,S as s,b as c,k as l,v as u}from"./shared-BLp3PbbW.js";import{t as d}from"./flask-conical-D3ofHU3O.js";import{t as f}from"./shield-check-DLlmt4Nd.js";import{t as p}from"./CodeEditor-DqHMt3P8.js";var m=t(`CheckCheck`,[[`path`,{d:`M18 6 7 17l-5-5`,key:`116fxf`}],[`path`,{d:`m22 10-7.5 7.5L13 16`,key:`ke71qq`}]]),h=e();function g({module:e}){return(0,h.jsxs)(i,{children:[(0,h.jsx)(r,{variant:`project`,chip:e??`Блок 12 · Проверяемая передача`,title:`Проверки операций API`,intro:`Закрепим договор Planner API настоящими HTTP-тестами: проверим ответы чтения, создания, полной замены, частичного изменения и удаления.`,tags:[{icon:(0,h.jsx)(d,{size:14}),label:`pytest и TestClient`},{icon:(0,h.jsx)(m,{size:14}),label:`HTTP-договор`},{icon:(0,h.jsx)(f,{size:14}),label:`изолированное состояние`}]}),(0,h.jsxs)(o,{number:`00`,title:`От одного маршрута к проверкам операций`,children:[(0,h.jsx)(a,{children:`Мы уже проверили GET /health и подготовили fixtures для отдельных тестов. Теперь проверим остальные операции: чтение, создание, полную замену, частичное изменение и удаление.`}),(0,h.jsx)(l,{variant:`connected`,items:[{title:`Точка старта`,description:`Настоящий FastAPI app, тест /health и fixtures api_service/api_client уже готовы. Каждый тест получает свои данные; основные маршруты и формы ответов знакомы.`},{title:`Новый вопрос`,description:`Как проверить ответ операции и убедиться, что нужные данные действительно изменились?`},{title:`Результат`,description:`В tests/test_api.py сохраним health-тест и добавим пять сценариев: чтение, создание, PUT, PATCH и DELETE.`}]}),(0,h.jsx)(`p`,{children:`Мы остаёмся в проекте StudyHub и работаем только с tests/test_api.py. Приложение, маршруты и хранилище не меняем. Существующий тест /health сохраняем. Fixtures api_service и api_client уже готовы: первая даёт сервис с временным JSON, вторая отправляет запросы через настоящий app.`}),(0,h.jsx)(`p`,{children:`Все запросы одной функции используют её временные данные. Поэтому POST и следующий GET увидят одну задачу. Другая функция получит отдельное состояние и не зависит от порядка запуска. В практике напишем пять сценариев: чтение, POST с последующим GET, PUT, PATCH и DELETE. Каждый новый тест запускается отдельно, затем проверяется общий набор.`})]}),(0,h.jsxs)(o,{number:`01`,title:`Статус и тело отвечают на разные вопросы`,children:[(0,h.jsx)(a,{children:`В каждом HTTP-тесте сначала проверим статус, затем данные ответа. Один факт не заменяет другой.`}),(0,h.jsx)(`p`,{children:`Объект response содержит как минимум две полезные для нас части. response.status_code сообщает, чем завершилась операция с точки зрения HTTP. response.json() разбирает JSON-тело в Python-значение: список, словарь, число или строку. Если тест проверяет только 200, он не замечает ошибочный список. Если он сравнивает JSON, не проверив статус, неудачный ответ может случайно содержать подходящее тело ошибки. Поэтому успешный тест явно утверждает ожидаемый статус и ожидаемое тело.`}),(0,h.jsx)(`p`,{children:`Читающие GET-маршруты возвращают 200. Список задач может быть пустым и всё равно успешно читается как JSON-список. GET /stats возвращает total для всех задач, open для незавершённых и done для выполненных. GET выбранного item возвращает одну задачу. Для этого заранее создадим её через api_service и возьмём фактический id. Рабочий data/tasks.json в этих тестах не участвует.`}),(0,h.jsx)(c,{question:`GET /tasks успешно прочитал пустую коллекцию. Какой результат проверяем?`,options:[`Статус 200 и JSON []`,`Статус 404 и JSON []`,`Только пустое тело content`],correctIndex:0,explanation:`Пустой список является существующей коллекцией без записей. Проверяем статус 200 и JSON-список; 404 относится к чтению отсутствующего item.`}),(0,h.jsx)(`p`,{children:`Тесты GET стоит держать раздельно. В одном подготовим запись и прочитаем коллекцию, в другом создадим две записи с разными состояниями и сверим total, open и done, в третьем запросим конкретный item. Каждый тест показывает одну гарантию, а при сбое его имя сразу подсказывает, какая операция требует внимания. Для подготовки используем готовый сервис, а для наблюдения ответа именно HTTP-клиент.`}),(0,h.jsx)(p,{caption:`Заготовка проверки списка, а не прямой вызов сервиса`,code:[`def test_list_returns_seeded_tasks(api_client, api_service):`,`    task = api_service.add_task("Записать вывод", 2)`,``,`    response = api_client.get("/tasks")`,``,`    assert response.status_code == 200`,`    assert response.json() == [`,`        {`,`            "id": task.id,`,`            "title": "Записать вывод",`,`            "priority": 2,`,`            "is_done": False,`,`        }`,`    ]`].join(`
`)}),(0,h.jsx)(`p`,{children:`Сервис здесь создаёт входные данные, но проверяемый путь остаётся HTTP-маршрутом. Фиксированный id не нужен: тест получает его из созданного объекта. Для item-ответа сравним id, title, priority и is_done. Это публичное представление, поэтому внутреннее поле tags в таком ответе не ожидаем.`}),(0,h.jsx)(`p`,{children:`Список и item различаются масштабом ответа. У списка верхний уровень JSON является массивом, даже когда внутри только одна запись. У item верхний уровень является объектом. Сравнение целиком полезно для небольшого стабильного публичного договора: оно заметит и неверное значение, и случайное появление внутреннего поля. В stats верхний уровень тоже объект, но его смысл задают счётчики, а не поля задачи. Мы выбираем проверку под результат каждой операции, а не копируем один assert для всех маршрутов.`}),(0,h.jsx)(`p`,{children:`В задании 1 примените это к трём GET: сравните список и item с публичными полями, а stats с тремя счётчиками. Каждый тест сам подготовит свои данные.`}),(0,h.jsx)(p,{caption:`Два других GET-теста из задания 1`,code:[`def test_stats_reports_all_tasks(api_client, api_service):`,`    api_service.add_task("Открытая задача", 1)`,`    done_task = api_service.add_task("Готовая задача", 3)`,`    api_service.mark_done(done_task.id)`,``,`    response = api_client.get("/stats")`,`    assert response.status_code == 200`,`    assert response.json() == {"total": 2, "open": 1, "done": 1}`,``,``,`def test_item_returns_public_task_without_tags(api_client, api_service):`,`    task = api_service.add_task("Прочитать ответ", 4, tags=["внутренний"])`,`    response = api_client.get("/tasks/" + str(task.id))`,``,`    assert response.status_code == 200`,`    assert response.json() == {`,`        "id": task.id,`,`        "title": "Прочитать ответ",`,`        "priority": 4,`,`        "is_done": False,`,`    }`].join(`
`)})]}),(0,h.jsxs)(o,{number:`02`,title:`Создание связываем с чтением по реальному id`,children:[(0,h.jsx)(a,{children:`POST создаёт запись и сообщает её id. Следующий GET в той же функции проверяет, что этот же ресурс доступен.`}),(0,h.jsx)(`p`,{children:`Для POST /tasks успешный статус равен 201, а тело содержит публичное представление созданной задачи. Не угадываем id по позиции и не задаём его вручную: читаем id из ответа сервера. Затем GET по этому значению проверяет результат через отдельный HTTP-запрос. Оба запроса выполняются через один api_client и относятся к одному тесту, поэтому второму запросу видны данные первого.`}),(0,h.jsx)(`p`,{children:`Порядок проверок помогает быстро найти причину сбоя. Сначала утверждаем 201, потому что только после успешного создания ожидаем JSON новой записи. Затем разбираем ответ, проверяем поля и отправляем GET. Наконец убеждаемся, что повторное чтение вернуло то же публичное состояние. Если сервер отдаст неверный id или не сохранит запись, проверка обнаружит это на конкретной границе.`}),(0,h.jsx)(u,{code:[`post_response = api_client.post(`,`    "/tasks",`,`    json={"title": "Записать вывод", "priority": 2},`,`)`,`assert post_response.status_code == 201`,`created = post_response.json()`,`item_path = "/tasks/" + str(created["id"])`,`read_response = api_client.get(item_path)`,`assert read_response.status_code == 200`,`assert read_response.json() == created`].join(`
`),steps:[{line:0,note:`Отправляем POST /tasks с title и priority в JSON-теле; response получает результат операции.`},{line:4,note:`Сначала проверяем ожидаемый статус создания: 201.`},{line:5,note:`Разбираем тело ответа; created теперь содержит id, который выдал сервер.`,vars:{created:`{'id': 7, 'title': 'Записать вывод', 'priority': 2, 'is_done': False}`}},{line:6,note:`Берём фактический id из ответа и собираем адрес одного item.`,vars:{item_path:`"/tasks/7"`}},{line:7,note:`По собранному адресу отправляется GET; ответ содержит уже созданный item.`},{line:8,note:`Убеждаемся, что чтение существующего item завершилось статусом 200.`},{line:9,note:`Сравниваем публичный объект GET с ответом POST; оба описывают одну созданную задачу.`}]}),(0,h.jsx)(`p`,{children:`В трассировке число 7 только наглядный пример значения из ответа. Тест никогда не зависит от того, какое именно число будет выдано. Он читает id и строит item-путь из полученного значения. Так мы не путаем идентификатор ресурса с номером строки в списке и не делаем тест хрупким из-за накопления данных.`}),(0,h.jsx)(`p`,{children:`Если разнести POST и GET по разным функциям, вторая функция начнёт с отдельного состояния и не увидит запись первой. Поэтому связанный сценарий остаётся внутри одного теста. Это не исключение из изоляции: изоляция разделяет функции, а не отдельные запросы внутри одной функции. Каждая функция сама решает, какое начальное состояние подготовить и какую последовательность наблюдений выполнить на нём.`}),(0,h.jsx)(`p`,{children:`В задании 2 повторите эту последовательность: POST, id из его ответа, затем GET с тем же клиентом.`})]}),(0,h.jsxs)(o,{number:`03`,title:`PUT и PATCH подтверждают разные изменения`,children:[(0,h.jsx)(a,{children:`PUT заменяет заданное представление целиком, а PATCH меняет отдельное поле. Ответ проверим вместе с тем, что должно сохраниться.`}),(0,h.jsx)(`p`,{children:`Для PUT мы заранее создаём задачу, отправляем полный набор полей модели обновления и сверяем весь ответ: фактический id, новый title, новый priority и значение is_done из тела. В этой модели обязательны все три входных поля: title, priority и is_done. Это не просто проверка того, что endpoint ответил 200; она фиксирует результат замены. Условия, при которых поле можно опустить или передать null, здесь не рассматриваем.`}),(0,h.jsx)(p,{caption:`Полное тело PUT и ожидаемые поля ответа`,code:[`response = api_client.put(`,`    "/tasks/" + str(task.id),`,`    json={"title": "Новый заголовок", "priority": 4, "is_done": False},`,`)`,``,`assert response.status_code == 200`,`assert response.json() == {`,`    "id": task.id,`,`    "title": "Новый заголовок",`,`    "priority": 4,`,`    "is_done": False,`,`}`].join(`
`)}),(0,h.jsx)(`p`,{children:`Полное сравнение ответа помогает заметить расхождение между HTTP-слоем и ожидаемым состоянием сервиса. Например, код 200 при старом title всё ещё означает, что маршрут ответил, но операция не выполнила ожидаемую замену. id при этом не меняется: обновление относится к уже выбранному ресурсу. Отдельная функция для PUT сама готовит запись, переводит её в выполненное состояние и показывает, что тело замены передаёт новое значение is_done.`}),(0,h.jsx)(`p`,{children:`PATCH проверим отдельной функцией. Сначала подготовим задачу как выполненную, затем отправим тело с is_done равным False. Это явный запрос изменить состояние обратно. Значение нельзя отбросить только потому, что оно ложно при проверке в условии. После PATCH мы сверяем is_done с False и убеждаемся, что title и priority остались прежними. Так тест замечает как потерю корректного false, так и случайную замену остальных полей.`}),(0,h.jsx)(s,{statement:(0,h.jsx)(h.Fragment,{children:`В PATCH тело с is_done: false просит применить значение false.`}),isTrue:!0,explanation:`Переданное булево False является явным значением, а не отсутствием поля. Ответ должен показать is_done=false и сохранить неизменяемые здесь title и priority.`}),(0,h.jsx)(p,{caption:`Сравниваем обновлённое поле и сохранённые поля`,code:[`task = api_service.add_task("Сверить ответ", 3)`,`api_service.mark_done(task.id)`,``,`response = api_client.patch(`,`    "/tasks/" + str(task.id),`,`    json={"is_done": False},`,`)`,``,`assert response.status_code == 200`,`assert response.json() == {`,`    "id": task.id,`,`    "title": "Сверить ответ",`,`    "priority": 3,`,`    "is_done": False,`,`}`].join(`
`)}),(0,h.jsx)(`p`,{children:`Здесь id снова получен от сервиса в рамках текущей тестовой функции, а сам запрос идёт через api_client. Сначала mark_done создаёт состояние, которое видно в начале проверки как True. Затем API должен применить переданное False. Такая подготовка делает тест различающим: если обработчик пропустит значение, итог останется True, и сравнение упадёт.`}),(0,h.jsx)(`p`,{children:`PUT и PATCH обращаются к одному типу item, но проверяют разные намерения. В тесте PUT мы передаём полный набор полей входной модели; в тесте PATCH явно передаём только выбранное изменение. В обоих сценариях status 200 означает успешный HTTP-ответ, а сравнение JSON показывает, что именно стало с задачей. Разделённые функции упрощают диагностику и сохраняют независимость состояния.`}),(0,h.jsx)(`p`,{children:`В задании 3 отдельно проверьте PUT с полным телом и PATCH с явным is_done: false. Сверьте все четыре публичных поля ответа.`})]}),(0,h.jsxs)(o,{number:`04`,title:`DELETE с кодом 204 не содержит JSON`,children:[(0,h.jsx)(a,{children:`После удаления проверим пустые байты ответа, а затем отдельным GET убедимся, что выбранный item отсутствует.`}),(0,h.jsx)(`p`,{children:`Успешный DELETE возвращает 204 No Content. Этот ответ подтверждает завершение удаления и не содержит JSON-тела. Поэтому для него проверяется response.content == b""; вызов response.json() будет пытаться разобрать пустые байты и завершится ошибкой декодирования. Чтобы проверить эффект операции, в той же функции сразу запрашиваем удалённый id и ожидаем 404.`}),(0,h.jsx)(n,{code:[`response = api_client.delete("/tasks/" + str(task_id))`,`assert response.status_code == 204`,`assert response.json() is None`].join(`
`),question:`Какая строка неверно проверяет успешный ответ 204?`,options:[`Строка со status_code: код 204 подходит.`,`Строка с response.json(): пустое тело нельзя разобрать как JSON.`,`Строка с DELETE: этот метод не может удалять задачу.`],correctIndex:1,explanation:`Маршрут DELETE возвращает 204 без тела. Проверим, что response.content пуст, затем прочитаем прежний id и ожидаем 404.`,fix:[`assert response.status_code == 204`,`assert response.content == b""`,`missing = api_client.get("/tasks/" + str(task_id))`,`assert missing.status_code == 404`].join(`
`)}),(0,h.jsx)(`p`,{children:`Последовательность важна: сначала сохраняем id существующей задачи, затем удаляем её, после чего проверяем пустой ответ и отсутствие ресурса. Нельзя проверять только статус удаления, потому что тесту важно подтвердить наблюдаемый результат. Не следует и разбирать JSON после 204. В этой точке пустое тело и последующий 404 являются двумя разными ожидаемыми фактами.`}),(0,h.jsx)(`p`,{children:`Статус ответа и его содержимое нельзя свести к одному универсальному утверждению. Для POST, PUT и PATCH мы читаем JSON и сравниваем его с ожидаемым объектом; для DELETE тело отсутствует по самому договору. Если вызвать json() для пустых байтов, клиент не получит Python-значение None: разбор оборвётся ошибкой, потому что в теле нет JSON-документа. Поэтому в тесте явно выбираем способ наблюдения, соответствующий форме ответа.`}),(0,h.jsx)(`p`,{children:`В задании 4 после DELETE проверьте пустое response.content, а затем выполните GET того же id и ожидайте 404.`})]}),(0,h.jsxs)(o,{number:`05`,title:`Что мы будем делать в практике`,children:[(0,h.jsx)(a,{children:`Добавим базовые проверки в существующий tests/test_api.py, не меняя приложение и готовую настройку клиента.`}),(0,h.jsx)(l,{variant:`connected`,items:[{title:`Подготовить данные`,description:`Создадим нужные записи через api_service и сохраним существующий health-тест.`},{title:`Отправить запрос`,description:`Все запросы отправим через api_client. Проверим статус и публичные поля ответа.`},{title:`Проверить результат`,description:`POST: GET по выданному id. PUT: прежний id. PATCH: false и сохранённое поле. DELETE: пустой ответ и 404 при чтении.`},{title:`Запустить тесты`,description:`Сначала запустим каждый из пяти сценариев отдельно, затем весь tests/test_api.py.`}]}),(0,h.jsx)(`p`,{children:`Практика идёт от чтения к созданию, обновлению и удалению. В каждом случае мы видим ожидаемый результат через HTTP-ответ и не полагаемся на порядок выполнения. Создание и подготовка данных через сервис задают вход, но суть проверки остаётся на HTTP-границе.`}),(0,h.jsx)(`p`,{children:`Чтобы запустить одну функцию, укажите файл и имя теста после двух двоеточий: python -m pytest -q tests/test_api.py::test_create_then_read_uses_server_id. Чтобы запустить весь файл, укажите только python -m pytest -q tests/test_api.py. В заключительном задании запустите каждую новую функцию отдельно, затем весь файл.`}),(0,h.jsx)(`p`,{children:`На выходе в одном файле сохранится прежняя проверка health и появятся проверки чтения, создания с последующим чтением, PUT, PATCH и DELETE. Запуск по отдельности подтверждает автономность каждого сценария, а общий запуск убеждает, что они не загрязняют данные друг друга.`})]})]})}export{g as Lesson57};